std::string s;
s.reserve(4096);       // Pre-allocate memory capacity
                       // Prevents reallocations/copying
                       // when appending up to 4096 chars.

s.append("data");
size_t current_cap = s.capacity(); // e.g., 4096
size_t current_size = s.size();    // e.g., 4

s.clear();             // Size = 0, Capacity remains 4096.

// Force release of excess capacity back to the heap:
s.shrink_to_fit();     // Capacity reduced (e.g., to SSO size or 0).

// Older/C++03 method for forcing deallocation:
std::string(s).swap(s);
// Capacity minimized.
